package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class SectionUnreadPolicyTest {
 private SectionUnreadPolicy.Chat chat(long id,int count,boolean mute){SectionUnreadPolicy.Chat c=new SectionUnreadPolicy.Chat(id,count,false,mute);c.category=4;return c;}
 private Set<Long> set(Long...ids){return new HashSet<>(Arrays.asList(ids));}
 @Test public void sampleCounts15Not20(){SectionConfig.Section s=new SectionConfig().add("Games");s.flags=4;assertEquals(15,SectionUnreadPolicy.sectionCount(s,Arrays.asList(chat(1,12,false),chat(2,5,true),chat(3,3,false)),Collections.emptyMap()));}
 @Test public void directAndSeveralFoldersUseUnionNotSum(){SectionConfig.Section s=new SectionConfig().add("S");s.include(1);s.tabs.addAll(Arrays.asList("tg:2","local:x"));Map<String,Set<Long>> f=new HashMap<>();f.put("tg:2",set(1L,2L));f.put("local:x",set(1L,2L,3L));assertEquals(15,SectionUnreadPolicy.sectionCount(s,Arrays.asList(chat(1,10,false),chat(2,2,false),chat(3,3,false),chat(3,3,false)),f));}
 @Test public void sectionExclusionOverridesFolderMembership(){SectionConfig.Section s=new SectionConfig().add("S");s.tabs.add("tg:2");s.exclude(1);assertEquals(2,SectionUnreadPolicy.sectionCount(s,Arrays.asList(chat(1,10,false),chat(2,2,false)),Collections.singletonMap("tg:2",set(1L,2L))));}
 @Test public void sameChatCountsInDifferentSectionsIndependently(){SectionConfig c=new SectionConfig();SectionConfig.Section a=c.add("A"),b=c.add("B");a.include(1);b.include(1);List<SectionUnreadPolicy.Chat> chats=Arrays.asList(chat(1,12,false));assertEquals(12,SectionUnreadPolicy.sectionCount(a,chats,Collections.emptyMap()));assertEquals(12,SectionUnreadPolicy.sectionCount(b,chats,Collections.emptyMap()));}
 @Test public void readTransitionAndNewMessageUpdateSystemVisibility(){SectionUnreadPolicy.Chat c=chat(1,3,false);assertTrue(SectionUnreadPolicy.matches(c,false));c.unread=0;assertFalse(SectionUnreadPolicy.matches(c,false));assertFalse(SectionUnreadPolicy.showSystem(true,false,false));assertTrue(SectionUnreadPolicy.showSystem(true,false,true));c.unread=2;assertTrue(SectionUnreadPolicy.matches(c,false));assertTrue(SectionUnreadPolicy.showSystem(true,true,false));}
 @Test public void nativeMuteSnapshotExpiryIsAppliedOnNextEvaluation(){SectionUnreadPolicy.Chat c=chat(1,5,true);assertFalse(SectionUnreadPolicy.matches(c,false));assertTrue(SectionUnreadPolicy.matches(c,true));c.muted=false;assertTrue(SectionUnreadPolicy.matches(c,false));assertEquals(5,SectionUnreadPolicy.count(Arrays.asList(c),id->true,false));}
 @Test public void mutedMentionStillDoesNotCountInOrdinarySection(){SectionConfig.Section s=new SectionConfig().add("S");s.include(1);SectionUnreadPolicy.Chat c=chat(1,12,true);c.mentioned=true;assertEquals(0,SectionUnreadPolicy.sectionCount(s,Arrays.asList(c),Collections.emptyMap()));}
 @Test public void accountSnapshotsDoNotShareCounts(){assertEquals(12,SectionUnreadPolicy.count(Arrays.asList(chat(1,12,false)),id->true,false));assertEquals(4,SectionUnreadPolicy.count(Arrays.asList(chat(1,4,false)),id->true,false));assertEquals(0,SectionUnreadPolicy.count(Collections.emptyList(),id->true,false));}
 @Test public void temporaryIncludeMutedDoesNotChangeOrdinarySectionPolicy(){SectionConfig.Section s=new SectionConfig().add("S");s.include(1);List<SectionUnreadPolicy.Chat> chats=Arrays.asList(chat(1,5,true));assertEquals(5,SectionUnreadPolicy.count(chats,id->true,true));assertEquals(0,SectionUnreadPolicy.sectionCount(s,chats,Collections.emptyMap()));}
 @Test public void compactFormattingAndZeroHaveNoSyntheticMessages(){assertEquals("99+",SectionUnreadPolicy.label(100,true));assertEquals("100",SectionUnreadPolicy.label(100,false));SectionUnreadPolicy.Chat c=new SectionUnreadPolicy.Chat(1,0,true,false);assertTrue(SectionUnreadPolicy.matches(c,false));assertEquals(0,SectionUnreadPolicy.count(Arrays.asList(c),id->true,false));assertFalse(SectionUnreadPolicy.showSystem(false,true,true));}
}
